194	// AllReduce performs a cross-thread reduction over a group of `threads`
195	// threads.
196	//
197	// Template parameters:
198	//   Reducer         - binary reduction functor (e.g. SumOp, MaxOp).
199	//   threads         - number of threads that span the reduce dimension,
200	//                     equal to extent * scale.
201	//   scale           - stride of participating threads in the thread index
202	//                     space. When the thread-to-data mapping is normalized as
203	//                       threadIdx = source * scale + ...
204	//                     `scale` is the stride between consecutive logical
205	//                     participants in the reduce dimension.
206	//                     The recursion terminates when threads == scale, meaning
207	//                     each reduce group has been collapsed to a single thread.
208	//                     Uses a recursive XOR-butterfly pattern: at each level,
209	//                     offset >= 32 goes through shared memory + barrier,
210	//                     offset < 32 uses warp shuffle (shfl_xor_sync).
211	//   thread_offset   - base thread index offset within the block.
212	//   Barrier         - barrier policy type (SyncThreadsBarrier or
213	//                     NamedBarrier<N>).
214	//   batch_size      - number of independent values to reduce in parallel,
215	//                     sharing synchronization barriers across all values.
216	//                     Default 1 preserves the original scalar behaviour.
217	//   workspace_stride - stride between per-channel slices in the shared-memory
218	//                     workspace (typically total threads in the block).
219	//                     Only used when batch_size > 1.
220	template <class Reducer, int threads, int scale, int thread_offset = 0,
221	          class Barrier = SyncThreadsBarrier, int batch_size = 1,
222	          int workspace_stride = 0>
223	struct AllReduce {
224	  static_assert(threads % scale == 0);
225	
226	  // Scalar interface (backward-compatible).
227	  template <typename T> static TL_DEVICE T run(T x, T *red_buf = nullptr) {
228	    if constexpr (threads == scale) {
229	      return x;
230	    } else {
231	      return butterfly_reduce_scalar(x, red_buf);
232	    }
233	  }
234	
235	  // Batch interface (named run_batch to avoid overload-resolution ambiguity
236	  // with the scalar run(T x, T*) when a pointer is passed as the first arg).
237	  template <typename T>
238	  static TL_DEVICE void run_batch(T *x, T *red_buf = nullptr) {
239	    if constexpr (threads == scale) {
240	      return;
241	    } else {
242	      butterfly_reduce_batch(x, red_buf);
243	    }
244	  }
245	
246	private:
247	  using Next = AllReduce<Reducer, threads / 2, scale, thread_offset, Barrier,
248	                         batch_size, workspace_stride>;
249	
250	  template <typename T>
251	  static TL_DEVICE T butterfly_reduce_scalar(T x, T *red_buf) {
252	    constexpr int offset = threads / 2;
253	    if constexpr (offset >= 32) {
254	      Barrier::template sync<1>();
255	      red_buf[threadIdx.x - thread_offset] = x;
256	      Barrier::template sync<2>();
257	      x = Reducer()(x, red_buf[(threadIdx.x - thread_offset) ^ offset]);
258	    } else {
259	      x = Reducer()(x, tl::shfl_xor_sync(uint32_t(-1), x, offset));
260	    }
261	    if constexpr (offset == scale) {
262	      return x;
263	    } else {
264	      return Next::run(x, red_buf);
265	    }
266	  }
267	
268	  template <typename T>
269	  static TL_DEVICE void butterfly_reduce_batch(T *x, T *red_buf) {
270	    constexpr int offset = threads / 2;
271	    if constexpr (offset >= 32) {
272	      Barrier::template sync<1>();
273	#pragma unroll
274	      for (int i = 0; i < batch_size; i++) {
275	        red_buf[(threadIdx.x - thread_offset) + i * workspace_stride] = x[i];
276	      }
277	      Barrier::template sync<2>();
278	#pragma unroll
279	      for (int i = 0; i < batch_size; i++) {
280	        x[i] =
281	            Reducer()(x[i], red_buf[((threadIdx.x - thread_offset) ^ offset) +
282	                                    i * workspace_stride]);
283	      }
284	    } else {
285	#pragma unroll
286	      for (int i = 0; i < batch_size; i++) {
287	        x[i] = Reducer()(x[i], tl::shfl_xor_sync(uint32_t(-1), x[i], offset));
288	      }
289	    }
290	    if constexpr (offset == scale) {
291	      return;
292	    } else {
293	      Next::run_batch(x, red_buf);
294	    }
295	  }
296	};
