298	// Reference:
299	// https://docs.nvidia.com/cuda/cuda-c-programming-guide/index.html#reduction
300	template <typename T, typename ReduceOp>
301	TL_DEVICE T warp_reduce(T value, ReduceOp op) {
302	  constexpr uint32_t mask = 0xffffffff;
303	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000) &&                       \
304	    (defined(__CUDA_ARCH_FEAT_SM100_ALL) || defined(__CUDA_ARCH_FEAT_SM100_F))
305	  float value_cast = 0.0f;
306	  if constexpr (std::is_same_v<T, half_t>) {
307	    value_cast = __half2float(value);
308	  } else if constexpr (std::is_same_v<T, bfloat16_t>) {
309	    value_cast = __bfloat162float(value);
310	  } else {
311	    value_cast = static_cast<float>(value);
312	  }
313	  if constexpr (std::is_same_v<ReduceOp, MaxOp> && !std::is_integral_v<T>) {
314	    float res;
315	    asm("redux.sync.max.f32 %0, %1, %2;"
316	        : "=f"(res)
317	        : "f"(value_cast), "r"(mask));
318	    return static_cast<T>(res);
319	  } else if constexpr (std::is_same_v<ReduceOp, MinOp> &&
320	                       !std::is_integral_v<T>) {
321	    float res;
322	    asm("redux.sync.min.f32 %0, %1, %2;"
323	        : "=f"(res)
324	        : "f"(value_cast), "r"(mask));
325	    return static_cast<T>(res);
326	  }
327	#endif
328	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
329	  auto run_reduce_sync = [&]<typename T_cast>(T_cast val) {
330	    if constexpr (std::is_same_v<ReduceOp, SumOp>) {
331	      return __reduce_add_sync(mask, val);
332	    } else if constexpr (std::is_same_v<ReduceOp, MaxOp>) {
333	      return __reduce_max_sync(mask, val);
334	    } else if constexpr (std::is_same_v<ReduceOp, MinOp>) {
335	      return __reduce_min_sync(mask, val);
336	    } else if constexpr (std::is_same_v<ReduceOp, BitAndOp>) {
337	      return __reduce_and_sync(mask, val);
338	    } else if constexpr (std::is_same_v<ReduceOp, BitOrOp>) {
339	      return __reduce_or_sync(mask, val);
340	    } else if constexpr (std::is_same_v<ReduceOp, BitXorOp>) {
341	      return __reduce_xor_sync(mask, val);
342	    }
343	  };
344	
345	  if constexpr (std::is_same_v<T, int32_t> || std::is_same_v<T, uint32_t>) {
346	    return run_reduce_sync(value);
347	  } else if constexpr (std::is_integral_v<T>) {
348	    return static_cast<T>(run_reduce_sync(static_cast<int32_t>(value)));
349	  }
350	#endif
351	  value = op(value, tl::shfl_xor_sync(mask, value, 16));
352	  value = op(value, tl::shfl_xor_sync(mask, value, 8));
353	  value = op(value, tl::shfl_xor_sync(mask, value, 4));
354	  value = op(value, tl::shfl_xor_sync(mask, value, 2));
355	  value = op(value, tl::shfl_xor_sync(mask, value, 1));
356	  return value;
357	}
358	
359	template <typename T> TL_DEVICE T warp_reduce_sum(T value) {
360	  return warp_reduce<T>(value, SumOp());
361	}
362	
363	template <typename T> TL_DEVICE T warp_reduce_max(T value) {
364	  return warp_reduce<T>(value, MaxOp());
365	}
366	
367	template <typename T> TL_DEVICE T warp_reduce_min(T value) {
368	  return warp_reduce<T>(value, MinOp());
369	}
370	
371	template <typename T> TL_DEVICE T warp_reduce_bitand(T value) {
372	  return warp_reduce<T>(value, BitAndOp());
373	}
374	
375	template <typename T> TL_DEVICE T warp_reduce_bitor(T value) {
376	  return warp_reduce<T>(value, BitOrOp());
377	}
378	
379	} // namespace tl
