19	template <int Bits, int N, int K, bool K_inner, int num_warp_n,
20	          typename Enable = void>
21	struct OperandTraits;
22	
23	template <int N, int K, int num_warp_n>
24	struct OperandTraits<16, N, K, true, num_warp_n,
25	                     typename std::enable_if<K % 64 == 32>::type> {
26	  using LayoutAtom = decltype(composition(
27	      Swizzle<2, 3, 3>{}, Layout<Shape<_8, _32>, Stride<_32, _1>>{}));
28	  using Layout = decltype(tile_to_shape(LayoutAtom{}, Shape<Int<N>, Int<K>>{}));
29	  using Copy = Copy_Traits<UniversalCopy<cute::uint64_t>>;
30	};
31	
32	template <int N, int K, int num_warp_n>
33	struct OperandTraits<16, N, K, true, num_warp_n,
34	                     typename std::enable_if<K % 64 == 0>::type> {
35	  using LayoutAtom = decltype(composition(
36	      Swizzle<4, 2, 4>{}, Layout<Shape<_16, _64>, Stride<_64, _1>>{}));
37	  using Layout = decltype(tile_to_shape(LayoutAtom{}, Shape<Int<N>, Int<K>>{}));
38	  using Copy = Copy_Traits<UniversalCopy<cute::uint64_t>>;
39	};
40	
41	template <int N, int K, int num_warp_n>
42	struct OperandTraits<16, N, K, false, num_warp_n,
43	                     typename std::enable_if<K % 64 == 0>::type> {
44	  using LayoutAtom = decltype(composition(
45	      Swizzle<4, 2, 4>{}, Layout<Shape<_64, _16>, Stride<_1, _64>>{}));
46	  using Layout = decltype(tile_to_shape(LayoutAtom{}, Shape<Int<N>, Int<K>>{}));
47	  using Copy = Copy_Traits<UniversalCopy<cute::uint16_t>>;
48	};
49	
50	template <int N, int K, int num_warp_n>
51	struct OperandTraits<16, N, K, false, num_warp_n,
52	                     typename std::enable_if<K % 64 == 32>::type> {
53	  using LayoutAtom = decltype(composition(
54	      Swizzle<3, 3, 3>{}, Layout<Shape<_64, _8>, Stride<_1, _64>>{}));
55	  using Layout = decltype(tile_to_shape(LayoutAtom{}, Shape<Int<N>, Int<K>>{},
56	                                        Step<_2, _1>{}));
57	  using Copy = Copy_Traits<UniversalCopy<cute::uint16_t>>;
58	};
59	
60	template <int M, int N, int K, int num_warp_m, int num_warp_n, bool trans_A,
61	          bool trans_B, bool clear_accum, typename A_type_raw,
62	          typename B_type_raw, typename C_type_raw>
63	class GemmTensorOp {
64	public:
65	  using A_type = A_type_raw;
66	  using B_type = B_type_raw;
67	  using C_type = C_type_raw;
68	
69	  using Instruction = DispatchInstruction<A_type, B_type, C_type>;
70	
71	  using OperandATraits =
72	      OperandTraits<sizeof_bits<A_type>::value, M, K, !trans_A, num_warp_m>;
73	  using OperandBTraits =
74	      OperandTraits<sizeof_bits<B_type>::value, N, K, trans_B, num_warp_n>;
75	
76	  using SmemLayoutA = typename OperandATraits::Layout;
77	  using SmemLayoutB = typename OperandBTraits::Layout;
78	  using SmemCopyA = Copy_Atom<typename OperandATraits::Copy, A_type>;
79	  using SmemCopyB = Copy_Atom<typename OperandBTraits::Copy, B_type>;
80	
81	  using TileMma = TiledMMA<typename Instruction::MMA,
82	                           Layout<Shape<Int<num_warp_m>, Int<num_warp_n>, _1>>,
83	                           Layout<Shape<_1, _1, _1>>>;
84	
85	  CUTE_DEVICE static void body(A_type_raw *pA, B_type_raw *pB, C_type_raw *pC) {
86	    const int tid = threadIdx.x;
87	    Tensor sA = make_tensor(make_smem_ptr(reinterpret_cast<A_type *>(pA)),
88	                            SmemLayoutA{});
89	    Tensor sB = make_tensor(make_smem_ptr(reinterpret_cast<B_type *>(pB)),
90	                            SmemLayoutB{});
91	
92	    TileMma tiled_mma;
93	    auto thr_mma = tiled_mma.get_thread_slice(tid);
94	    auto tiled_copy_A = make_tiled_copy_A(SmemCopyA{}, tiled_mma);
95	    auto tiled_copy_B = make_tiled_copy_B(SmemCopyB{}, tiled_mma);
96	    auto thr_copy_A = tiled_copy_A.get_thread_slice(tid);
97	    auto thr_copy_B = tiled_copy_B.get_thread_slice(tid);
98	
99	    Tensor tCrA = thr_mma.partition_fragment_A(sA);
100	    Tensor tCrB = thr_mma.partition_fragment_B(sB);
101	    Tensor tCsA = thr_copy_A.partition_S(sA);
102	    Tensor tCsB = thr_copy_B.partition_S(sB);
103	
104	    Tensor tCrA_copy_view = thr_copy_A.retile_D(tCrA);
105	    Tensor tCrB_copy_view = thr_copy_B.retile_D(tCrB);
106	
107	    Tensor acc =
108	        make_tensor(make_rmem_ptr(reinterpret_cast<C_type *>(pC)),
109	                    partition_shape_C(tiled_mma, Shape<Int<M>, Int<N>>{}));
110	
111	    if constexpr (clear_accum) {
112	      clear(acc);
113	    }
114	
115	    for (int k = 0; k < size<2>(tCrA); ++k) {
116	      copy(tiled_copy_A, tCsA(_, _, k), tCrA_copy_view(_, _, k));
117	      copy(tiled_copy_B, tCsB(_, _, k), tCrB_copy_view(_, _, k));
118	      gemm(tiled_mma, tCrA(_, _, k), tCrB(_, _, k), acc);
119	    }
120	  }
121	
122	  CUTE_DEVICE static void body_rs(A_type_raw *pA, B_type_raw *pB,
123	                                  C_type_raw *pC) {
124	    const int tid = threadIdx.x;
125	    Tensor sB = make_tensor(make_smem_ptr(reinterpret_cast<B_type *>(pB)),
126	                            SmemLayoutB{});
127	
128	    TileMma tiled_mma;
129	    auto thr_mma = tiled_mma.get_thread_slice(tid);
130	    auto tiled_copy_B = make_tiled_copy_B(SmemCopyB{}, tiled_mma);
131	    auto thr_copy_B = tiled_copy_B.get_thread_slice(tid);
132	
133	    Tensor tCrB = thr_mma.partition_fragment_B(sB);
134	    Tensor tCsB = thr_copy_B.partition_S(sB);
135	
136	    Tensor tCrB_copy_view = thr_copy_B.retile_D(tCrB);
137	
138	    Tensor acc =
139	        make_tensor(make_rmem_ptr(reinterpret_cast<C_type *>(pC)),
140	                    partition_shape_C(tiled_mma, Shape<Int<M>, Int<N>>{}));
141	    Tensor tCrA =
142	        make_tensor(make_rmem_ptr(reinterpret_cast<A_type *>(pA)),
143	                    partition_shape_A(tiled_mma, Shape<Int<M>, Int<K>>{}));
144	
145	    if constexpr (clear_accum) {
146	      clear(acc);
147	    }
148	
149	    for (int k = 0; k < size<2>(tCrA); ++k) {
150	      copy(tiled_copy_B, tCsB(_, _, k), tCrB_copy_view(_, _, k));
151	      gemm(tiled_mma, tCrA(_, _, k), tCrB(_, _, k), acc);
152	    }
153	  }
154	};
