161	          bool trans_B, bool clear_accum, int kPack, typename A_type,
162	          typename B_type, typename C_type>
163	MCTLASS_DEVICE void gemm_ss(A_type *pA, B_type *pB, C_type *accum) {
164	  using MMA = cute::GemmTensorOp<M, N, K, num_warp_m, num_warp_n, trans_A,
165	                                 trans_B, clear_accum, A_type, B_type, C_type>;
166	  MMA::body(pA, pB, accum);
167	}
